#!/usr/bin/env python3
"""
Generates `vendor:android/java`, JNI wrappers for the Java APIs in an Android SDK platform's `android.jar`.

Only the Java packages in PACKAGES get methods, fields and constants. Classes they refer to from other
packages get a type, so every signature can be generated as is.

A Java reference is a pointer to its class's struct, like `jobject` in C++'s `jni.h`. The structs are
zero-size and never dereferenced:

	Activity :: struct #raw_union {
		using ContextThemeWrapper: ContextThemeWrapper, // `^Activity` converts to any ancestor implicitly
		Window_Callback:           Window_Callback,     // `&activity.Window_Callback` for each interface
	}

Every wrapper returns its exception as the last result, so nothing is left pending:

	window := java.Activity_getWindow(activity) or_return

The JNIEnv is implicit: `android.jni_env()`. Classes, methods and fields are looked up on first use and cached.

Integer slots that take constants are typed: the ones @IntDef and @LongDef annotate (the SDK's annotations.zip),
and the ones `table.py`, the reviewed table, names. They become Odin enums, bit_sets and bit_fields.

Usage:
	python vendor/android/java/_gen/generate.py [--sdk <path/to/sdk>] [--platform android-37.2] [--stats]

The SDK path defaults to ODIN_ANDROID_SDK.
"""

import argparse
import collections
import fnmatch
import html
import os
import re
import struct
import sys
import xml.etree.ElementTree as ET
import zipfile

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import classfile as cf
import table as TABLE


GENERATED_MARKER = "// Generated by vendor/android/java/_gen/generate.py from the Android SDK. DO NOT EDIT."

OUT_DIR = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
PACKAGE = "android_java"

# Odin's minimum Android API level. Newer classes and members get an `// API level N` comment.
MIN_API_LEVEL = 29

# Java packages whose classes get methods, fields and constants.
PACKAGES = [
	"android.app",
	"android.content",
	"android.content.pm",
	"android.content.res",
	"android.graphics",
	"android.hardware",
	"android.net",
	"android.os",
	"android.text",
	"android.util",
	"android.view",
	"android.view.inputmethod",
	"android.widget",
	"java.io",
	"java.lang",
	"java.lang.reflect",
	"java.nio",
	"java.util",
]

# When classes in different packages share a name, the first of these packages keeps the plain name.
# The others, and every clash none of these packages is in, are prefixed with their last package name.
NAME_PRIORITY = [
	"java.lang", "java.lang.reflect", "java.util", "java.io", "java.nio",
	"android.app", "android.content", "android.os", "android.view", "android.graphics", "android.widget",
	"android.text", "android.util", "android.net", "android.hardware", "android.media",
]

# Classes whose types are written by hand in `java.odin`. Their members are still generated.
HAND_WRITTEN_TYPES = {"java/lang/Object"}

# Classes the hand-written runtime needs, whatever PACKAGES says.
RUNTIME_CLASSES = ["java/lang/Object", "java/lang/Throwable", "java/lang/String", "java/lang/Class"]

# Names declared by hand in `java.odin`.
HAND_WRITTEN_NAMES = {
	"Object", "Array", "BooleanArray", "ByteArray", "CharArray", "ShortArray", "IntArray", "LongArray",
	"FloatArray", "DoubleArray", "Cached_Class", "Cached_Method", "Cached_Field",
}

PRIMITIVES = {
	#    Odin type  jvalue  JNI suffix   overload suffix
	"Z": ("bool",   "z",    "Boolean",   "bool"),
	"B": ("i8",     "b",    "Byte",      "byte"),
	"C": ("u16",    "c",    "Char",      "char"),
	"S": ("i16",    "s",    "Short",     "short"),
	"I": ("i32",    "i",    "Int",       "int"),
	"J": ("i64",    "j",    "Long",      "long"),
	"F": ("f32",    "f",    "Float",     "float"),
	"D": ("f64",    "d",    "Double",    "double"),
}

ODIN_KEYWORDS = {
	"asm", "auto_cast", "bit_field", "bit_set", "break", "case", "cast", "context", "continue",
	"defer", "distinct", "do", "dynamic", "else", "enum", "fallthrough", "for", "foreign", "if",
	"import", "in", "map", "matrix", "not_in", "or_break", "or_continue", "or_else", "or_return",
	"package", "proc", "return", "struct", "switch", "transmute", "typeid", "union", "using",
	"when", "where", "nil", "true", "false",
}

# Names the generated procedures use themselves.
RESERVED_PARAMS = {"self", "result", "exception", "android", "jni_env", "jni_class", "jni_id", "jni_args", "jni_cache"}


class GenError(Exception):
	pass


def odin_ident(name):
	if name in ODIN_KEYWORDS or name in RESERVED_PARAMS:
		return name + "_"
	return name


def package_of(name):
	return name.rsplit("/", 1)[0].replace("/", ".") if "/" in name else ""


def java_name(name):
	return name.replace("/", ".").replace("$", ".")


#
# Inputs
#

def api_level(since):
	# Minor SDK versions are written `36.1`; the API level is the major part.
	return int(since.split(".")[0])


class Platform:
	def __init__(self, sdk, platform):
		self.dir  = os.path.join(sdk, "platforms", platform)
		self.name = platform
		if not os.path.isdir(self.dir):
			raise GenError(f"{self.dir} does not exist")

		with zipfile.ZipFile(os.path.join(self.dir, "android.jar")) as jar:
			self.classes = {}
			for entry in jar.namelist():
				if entry.endswith(".class"):
					c = cf.ClassFile(jar.read(entry))
					self.classes[c.name] = c

		stubs = os.path.join(self.dir, "android-stubs-src.jar")
		self.stubs = zipfile.ZipFile(stubs) if os.path.exists(stubs) else None

		self.annotations = os.path.join(self.dir, "data", "annotations.zip")
		if not os.path.exists(self.annotations):
			raise GenError(f"{self.annotations} does not exist")

		self.since = {}
		versions = os.path.join(self.dir, "data", "api-versions.xml")
		if os.path.exists(versions):
			for cls in ET.parse(versions).getroot().iter("class"):
				name = cls.get("name")
				class_since = api_level(cls.get("since", "1"))
				self.since[name] = class_since
				for m in cls:
					if m.tag in ("method", "field") and m.get("since"):
						self.since[f"{name}#{m.get('name')}"] = api_level(m.get("since"))


#
# Parameter names, from the stub sources
#

STRIP_RE      = re.compile(r'/\*.*?\*/|//[^\n]*|"(?:\\.|[^"\\\n])*"|\'(?:\\.|[^\'\\\n])*\'', re.S)
ANNOTATION_RE = re.compile(r'@(?!interface\b)[\w.]+(?:\s*\([^()]*\))?\s*')
TYPE_DECL_RE  = re.compile(r'\b(?:class|interface|enum|@interface)\s+(\w+)')
METHOD_RE     = re.compile(r'^\s*(?:public|protected)\b[^(=]*?\b(\w+)\s*\(([^)]*)\)\s*(?:throws\b[^{;]*)?[{;]')


def strip_java(text):
	def blank(m):
		s = m.group(0)
		return "\n" * s.count("\n") if s.startswith("/") else '""'
	return STRIP_RE.sub(blank, text)


def split_params(s):
	out, depth, cur = [], 0, ""
	for ch in s:
		if ch == "<":
			depth += 1
		elif ch == ">":
			depth -= 1
		if ch == "," and depth == 0:
			out.append(cur.strip())
			cur = ""
		else:
			cur += ch
	if cur.strip():
		out.append(cur.strip())
	return out


def source_param_names(platform, outer):
	"""{(binary class name, method name, parameter count): [[(type as written, name)], ...]}"""
	result = {}
	if platform.stubs is None:
		return result
	try:
		text = platform.stubs.read(outer + ".java").decode("utf-8", "replace")
	except KeyError:
		return result

	stack = []  # [(binary name, brace depth inside its body)]
	depth = 0
	for line in strip_java(text).splitlines():
		line = ANNOTATION_RE.sub("", line)
		decl = TYPE_DECL_RE.search(line)
		if decl and "(" not in line[:decl.start()] and line.rstrip().endswith("{"):
			name = outer if not stack else f"{stack[-1][0]}${decl.group(1)}"
			stack.append((name, depth+1))
		elif stack and depth == stack[-1][1]:
			m = METHOD_RE.match(line)
			if m:
				owner  = stack[-1][0]
				method = m.group(1)
				if method == owner.rsplit("/", 1)[-1].rsplit("$", 1)[-1]:
					method = "<init>"
				params = []
				for p in split_params(m.group(2)):
					parts = re.sub(r"<.*>", "", p).replace("final ", "").replace("...", "[]").split()
					if len(parts) < 2:
						params = None
						break
					params.append(("".join(parts[:-1]), parts[-1]))
				if params is not None:
					result.setdefault((owner, method, len(params)), []).append(params)

		depth += line.count("{") - line.count("}")
		while stack and depth < stack[-1][1]:
			stack.pop()
	return result


def source_java_type(desc):
	"""A field descriptor as the stub sources write it, e.g. `android.view.ViewGroup.LayoutParams[]`."""
	dims = len(desc) - len(desc.lstrip("["))
	base = desc[dims:]
	if base[0] == "L":
		base = java_name(base[1:-1])
	else:
		base = {"Z": "boolean", "B": "byte", "C": "char", "S": "short", "I": "int", "J": "long", "F": "float", "D": "double"}[base]
	return base + "[]" * dims


JAVA_PRIMITIVES = {"boolean", "byte", "char", "short", "int", "long", "float", "double"}


def pick_param_names(candidates, descs):
	"""The parameter names of the source overload whose types match the descriptor's."""
	if not candidates:
		return None
	if len(candidates) == 1:
		chosen = candidates[0]
	else:
		want = [source_java_type(d) for d in descs]

		def matches(params, generic):
			for (typ, _), w in zip(params, want):
				if typ == w:
					continue
				# Classes are fully qualified, so an unqualified name is a type variable (`T`, `E[]`),
				# which erases to a class type with as many dimensions.
				base, dims = typ.rstrip("[]"), typ.count("[]")
				w_base, w_dims = w.rstrip("[]"), w.count("[]")
				if not generic or "." in base or base in JAVA_PRIMITIVES or w_base in JAVA_PRIMITIVES or dims != w_dims:
					return False
			return True

		exact = [c for c in candidates if matches(c, False)]
		found = exact or [c for c in candidates if matches(c, True)]
		if not found or any([n for _, n in c] != [n for _, n in found[0]] for c in found):
			return None
		chosen = found[0]
	names = [odin_ident(n) for _, n in chosen]
	if len(set(names)) != len(names):
		return None
	return names


#
# The model
#

def is_public(c):
	return bool(c.access & cf.ACC_PUBLIC)


def is_interface(c):
	return bool(c.access & cf.ACC_INTERFACE)


def is_inner_class(c):
	"""Whether `c` is a non-static nested class, whose instances belong to an outer instance."""
	return "$" in c.name and c.name in c.inner and not c.inner[c.name] & cf.ACC_STATIC


def is_anonymous(name):
	return re.search(r"\$\d", name) is not None


def members(c):
	"""The members of `c` that get wrappers or constants."""
	out = []
	for f in c.fields:
		if f.access & cf.ACC_PUBLIC and not f.access & cf.ACC_SYNTHETIC:
			out.append(f)
	for m in c.methods:
		if not m.access & cf.ACC_PUBLIC or m.access & (cf.ACC_SYNTHETIC | cf.ACC_BRIDGE):
			continue
		if m.name == "<clinit>":
			continue
		if m.name == "<init>" and c.access & (cf.ACC_ABSTRACT | cf.ACC_INTERFACE):
			continue
		out.append(m)
	return out


def descriptor_classes(desc):
	if desc.startswith("("):
		params, ret = cf.parse_descriptor(desc)
		descs = params + [ret]
	else:
		descs = [desc]
	for d in descs:
		d = d.lstrip("[")
		if d.startswith("L"):
			yield d[1:-1]


class JavaClass:
	def __init__(self, cls, selected):
		self.cls      = cls
		self.name     = cls.name
		self.selected = selected  # whether its members are generated
		self.odin     = None
		self.parent   = None      # the binary name behind the `using` field
		self.views    = []        # interface binary names


def build_model(platform, packages):
	classes  = platform.classes
	selected = set(packages)

	chosen = {
		n for n, c in classes.items()
		if is_public(c) and not is_anonymous(n) and package_of(n) in selected and not n.endswith("package-info")
	}

	model = {}

	def need(name):
		if name in model or name not in classes:
			return
		c = classes[name]
		model[name] = JavaClass(c, name in chosen)
		if c.super:
			need(c.super)
		for i in c.interfaces:
			need(i)

	for name in RUNTIME_CLASSES:
		need(name)
	for name in sorted(chosen):
		need(name)
		for m in members(classes[name]):
			for ref in descriptor_classes(m.descriptor):
				need(ref)

	# The `using` parent: the superclass, an interface's first superinterface, or Object.
	for jc in model.values():
		c = jc.cls
		if jc.name == "java/lang/Object":
			continue
		if is_interface(c):
			supers = [i for i in c.interfaces if i in model]
			jc.parent = supers[0] if supers else "java/lang/Object"
		else:
			jc.parent = c.super if c.super in model else "java/lang/Object"

	# Views: every interface the type implements, directly or not, that its parent chain does not reach.
	closures = {}

	def interface_closure(name):
		if name not in closures:
			out = set()
			c = classes[name]
			for i in c.interfaces:
				if i in model:
					out.add(i)
					out |= interface_closure(i)
			if c.super in model:
				out |= interface_closure(c.super)
			closures[name] = out
		return closures[name]

	reaches = {}

	def reachable(name):
		"""Every type a `^name` reaches through its `using` chain and its views, itself included."""
		if name not in reaches:
			jc = model[name]
			inherited = reachable(jc.parent) if jc.parent else set()
			jc.views = sorted(interface_closure(name) - inherited - {name})
			reaches[name] = inherited | set(jc.views) | {name}
		return reaches[name]

	for name in sorted(model):
		reachable(name)

	assign_names(model)
	return model, chosen


def assign_names(model):
	def priority(name):
		pkg = package_of(name)
		return NAME_PRIORITY.index(pkg) if pkg in NAME_PRIORITY else len(NAME_PRIORITY)

	def qualified(name, k):
		return "_".join(package_of(name).split(".")[-k:]) + "_" + name.rsplit("/", 1)[-1].replace("$", "_")

	by_plain = collections.defaultdict(list)
	for n in model:
		by_plain[n.rsplit("/", 1)[-1].replace("$", "_")].append(n)

	for plain, names in by_plain.items():
		reserved = plain in HAND_WRITTEN_NAMES and names[0] not in HAND_WRITTEN_TYPES
		if len(names) == 1 and not reserved:
			model[names[0]].odin = plain
			continue
		names.sort(key=lambda n: (priority(n), n))
		winner = None
		if not reserved and priority(names[0]) < len(NAME_PRIORITY) and (len(names) == 1 or priority(names[0]) < priority(names[1])):
			winner = names[0]
		for n in names:
			if n == winner:
				model[n].odin = plain
				continue
			k = 1
			while any(qualified(n, k) == qualified(o, k) for o in names if o != n):
				k += 1
			model[n].odin = qualified(n, k)

	seen = {}
	for n, jc in model.items():
		if jc.odin in seen:
			raise GenError(f"{java_name(n)} and {java_name(seen[jc.odin])} are both named {jc.odin}")
		seen[jc.odin] = n


#
# Odin spelling
#

def odin_ref(model, desc):
	"""The Odin type of a field descriptor."""
	if desc in PRIMITIVES:
		return PRIMITIVES[desc][0]
	return "^" + odin_struct(model, desc)


def odin_struct(model, desc):
	if desc.startswith("["):
		element = desc[1:]
		if element in PRIMITIVES:
			return PRIMITIVES[element][2] + "Array"
		return f"Array({odin_struct(model, element)})"
	return model[desc[1:-1]].odin


def overload_suffix(model, desc):
	if desc in PRIMITIVES:
		return PRIMITIVES[desc][3]
	if desc.startswith("["):
		element = desc[1:]
		if element in PRIMITIVES:
			return PRIMITIVES[element][2] + "Array"
		return overload_suffix(model, element) + "Array"
	return model[desc[1:-1]].odin


def call_kind(desc):
	if desc == "V":
		return "Void"
	if desc in PRIMITIVES:
		return PRIMITIVES[desc][2]
	return "Object"


def odin_string(s):
	# Join the surrogate pairs of modified UTF-8; a lone surrogate stays as its 3 bytes.
	s = s.encode("utf-16-le", "surrogatepass").decode("utf-16-le", "surrogatepass")
	out = []
	for ch in s:
		o = ord(ch)
		if ch == '"':
			out.append('\\"')
		elif ch == "\\":
			out.append("\\\\")
		elif ch == "\n":
			out.append("\\n")
		elif ch == "\t":
			out.append("\\t")
		elif ch == "\r":
			out.append("\\r")
		elif o < 0x20 or o == 0x7f:
			out.append(f"\\x{o:02x}")
		elif 0xD800 <= o <= 0xDFFF:
			out.append("".join(f"\\x{b:02x}" for b in ch.encode("utf-8", "surrogatepass")))
		elif o > 0x7e and not ch.isprintable():
			out.append(f"\\u{o:04x}" if o <= 0xFFFF else f"\\U{o:08x}")
		else:
			out.append(ch)
	return '"' + "".join(out) + '"'


def odin_float(v, single):
	bits = struct.pack(">f", v) if single else struct.pack(">d", v)
	if v != v or v in (float("inf"), float("-inf")):
		return "0h" + bits.hex()
	if single:
		# The shortest decimal that reads back as the same f32. Rounding Float.MAX_VALUE up overflows.
		for precision in range(1, 10):
			r = f"{v:.{precision}g}"
			if abs(float(r)) <= 3.4028234663852886e38 and struct.pack(">f", float(r)) == bits:
				break
	else:
		r = repr(v)
	if "e" in r:
		mantissa, exponent = r.split("e")
		if "." not in mantissa:
			mantissa += ".0"
		return f"{mantissa}e{int(exponent)}"
	return r if "." in r else r + ".0"


def odin_constant(desc, value):
	kind, v = value
	if desc == "Z":
		return "true" if v else "false"
	if kind == "string":
		return odin_string(v)
	if kind in ("float", "double"):
		return odin_float(v, kind == "float")
	return str(v)


#
# Typed integers: @IntDef groups and table.py's types become Odin enums, bit_sets and bit_fields
#

INT_BITS = {"i32": 32, "u32": 32, "i64": 64, "u64": 64, "u8": 8, "u16": 16}
ANNOTATED_ITEM_RE = re.compile(r"^(\S+) (?:(\S+) )?([\w$]+)\((.*)\)(?: (\d+))?$")


class TypedInt:
	"""An Odin enum, bit_set or bit_field over Java constants."""

	def __init__(self, name, kind, owner, consts):
		self.name     = name
		self.kind     = kind    # "enum", "bit_set" or "bit_field"
		self.owner    = owner   # the binary class it is emitted with
		self.consts   = consts  # [(binary class, field)]
		self.backing  = None
		self.part_of  = None    # a bit_field's field enum: that bit_field, which emits it
		self.element  = None    # bit_set: its element enum
		self.members  = {}      # constant -> enum member, or bit_set element
		self.bits     = {}      # bit_set: element -> bit
		self.typed    = []      # constants that become typed constants, `<name>_<NAME>`
		self.short    = {}      # typed constant -> NAME
		self.literals = {}      # typed constant -> Odin literal
		self.values   = {}      # field enum: member -> value
		self.enums    = []      # bit_field: the field enums it declares
		self.fields   = []      # bit_field: (name, type, bits)
		self.alone    = {}      # bit_field: field enum at bit 0 -> the constants that set only that field


class Slot:
	"""An int or long parameter, result or field of a bound class."""

	def __init__(self, cls, member, desc, where, jtype, name, key):
		self.cls    = cls
		self.member = member
		self.desc   = desc
		self.where  = where     # parameter index, "return" or "field"
		self.jtype  = jtype     # "I" or "J"
		self.name   = name      # the parameter's name, or the method's or field's
		self.key    = key       # its key in annotations.zip
		self.intdef = None      # the component of @IntDef constants it takes

	def label(self):
		"""The key table.py's rules match: the parameter name, "result" or "field"."""
		return "result" if self.where == "return" else "field" if self.where == "field" else self.name


def table_members(spec, names):
	"""The names a table.py members spec picks, in the order of `names`."""
	if spec == "*":
		return list(names)
	if isinstance(spec, str):
		return [n for n in names if n.startswith(spec)]
	picked = []
	for n in names:
		hit = False
		for pattern in spec:
			negated = pattern.startswith("!")
			if fnmatch.fnmatchcase(n, pattern[1:] if negated else pattern):
				hit = not negated
		if hit:
			picked.append(n)
	return picked


def shared_prefix(names):
	"""The prefix all names share, up to its last `_`."""
	if len(names) < 2:
		return ""
	p = os.path.commonprefix(names)
	return p[:p.rfind("_") + 1]


def member_name(type_name, short):
	"""`short` as an Odin identifier: `_90`, or `NUM0` for a number key."""
	if short[:1].isdigit():
		return ("NUM" if type_name in TABLE.NUMBER_KEYS and short.isdigit() else "_") + short
	return short


def element_name(name):
	"""The element enum of a bit_set, as in darwin: the singular, or `Flag` added."""
	if name.endswith("Flags"):
		return name[:-1]
	if name.endswith(("uses", "sses", "xes")):
		return name[:-2]
	if name.endswith("ies"):
		return name[:-3] + "y"
	if name.endswith("s") and not name.endswith("ss"):
		return name[:-1]
	return name + "Flag"


def camel(words):
	return "".join(w[:1].upper() + w[1:].lower() for w in words if w)


def read_intdefs(platform):
	"""{annotations.zip key: (constants as Java names, flag, long)} for every @IntDef and @LongDef."""
	out = {}
	with zipfile.ZipFile(platform.annotations) as z:
		for entry in z.namelist():
			if not entry.endswith(".xml"):
				continue
			for item in ET.fromstring(z.read(entry)).iter("item"):
				name = html.unescape(item.get("name"))
				m = ANNOTATED_ITEM_RE.match(name)
				if m:
					cls, ret, member, params, index = m.groups()
					types = tuple(re.sub(r"<.*>", "", p).replace("...", "[]").strip() for p in split_params(params))
					key = (cls, member if ret is not None else "<init>", types, int(index) if index is not None else "return")
				else:
					parts = name.split(" ")
					if len(parts) != 2:
						continue
					key = (parts[0], parts[1], None, "field")
				for a in item.iter("annotation"):
					kind = a.get("name").rsplit(".", 1)[-1]
					if kind in ("IntDef", "LongDef"):
						vals = {v.get("name"): v.get("val") for v in a.iter("val")}
						consts = [c.strip() for c in vals.get("value", "{}").strip("{}").split(",") if c.strip()]
						out[key] = (consts, vals.get("flag") == "true", kind == "LongDef")
	return out


class Types:
	"""Every typed integer, and the type of each slot."""

	def __init__(self, platform, model, chosen, param_names):
		self.platform = platform
		self.model    = model
		self.types    = {}  # name -> TypedInt
		self.slots    = {}  # (class, member, descriptor, where) -> TypedInt
		classes       = platform.classes

		# Every int and long constant.
		self.values = collections.defaultdict(dict)  # class -> {field: value}
		self.longs  = set()                          # (class, field) of long constants
		for name, c in classes.items():
			for f in c.fields:
				if f.access & cf.ACC_STATIC and f.access & cf.ACC_FINAL and f.constant is not None and f.descriptor in ("I", "J"):
					self.values[name][f.name] = f.constant[1]
					if f.descriptor == "J":
						self.longs.add((name, f.name))
		by_java = {java_name(n): n for n in classes}

		def resolve(java):
			cls, _, field = java.rpartition(".")
			b = by_java.get(cls)
			return (b, field) if b is not None and field in self.values.get(b, {}) else None

		slots = self.collect_slots(classes, chosen, param_names)
		self.all_slots = slots

		# Slots @IntDef annotates, or annotates an overridden method's.
		intdefs = read_intdefs(platform)
		ancestors = {}

		def ancestors_of(name):
			if name not in ancestors:
				out, todo = [], [name]
				while todo:
					c = classes.get(todo.pop(0))
					for a in ([c.super] if c and c.super else []) + (list(c.interfaces) if c else []):
						if a not in out:
							out.append(a)
							todo.append(a)
				ancestors[name] = out
			return ancestors[name]

		annotated = []
		for s in slots:
			found = intdefs.get(s.key)
			if found is None and s.where != "field" and s.member != "<init>":
				for a in ancestors_of(s.cls):
					found = intdefs.get((java_name(a),) + s.key[1:])
					if found is not None:
						break
			if found is None:
				continue
			consts, flag, is_long = found
			resolved = [resolve(c) for c in consts]
			# A @LongDef on an int slot, or the other way around, does not type it.
			if resolved and None not in resolved and is_long == (s.jtype == "J"):
				annotated.append((s, frozenset(resolved), flag, is_long))

		# Groups sharing a constant are one group, kept apart by width.
		parent = {}

		def find(x):
			while parent.setdefault(x, x) != x:
				x = parent[x]
			return x

		for s, consts, flag, is_long in annotated:
			first = (is_long, next(iter(sorted(consts))))
			for c in consts:
				parent[find((is_long, c))] = find(first)
		components = {}
		for s, consts, flag, is_long in annotated:
			root = find((is_long, next(iter(sorted(consts)))))
			comp = components.setdefault(root, {"consts": set(), "flag": False, "long": is_long, "slots": [], "type": None})
			comp["consts"] |= consts
			comp["flag"] |= flag
			comp["slots"].append(s)
			s.intdef = comp
		self.components = list(components.values())

		def component_of(ref):
			"""The group holding a constant. One in both an @IntDef and a @LongDef group names the @IntDef one."""
			cls, const = ref[1:].rsplit(".", 1)
			found = [c for c in self.components if (cls, const) in c["consts"]]
			if len(found) > 1:
				found = [c for c in found if not c["long"]]
			if len(found) != 1:
				raise GenError(f"{ref} is in {len(found)} @IntDef groups")
			return found[0]

		raw = [component_of(ref) for ref in TABLE.RAW_GROUPS]
		self.build_table_types(classes)

		# A group inside a bit_field's constants, or a new type's, takes that type. The rest get one of their own.
		bit_fields = [t for t in self.types.values() if t.kind == "bit_field"]
		new_types  = [self.types[n] for n in TABLE.NEW_TYPES]
		own = []
		for comp in self.components:
			if any(comp is r for r in raw):
				continue
			target = next((t for t in bit_fields if comp["consts"] <= set(t.consts)), None)
			target = target or next((t for t in new_types if comp["consts"] <= set(t.consts)), None)
			if target is not None and INT_BITS[target.backing] != (64 if comp["long"] else 32):
				raise GenError(f"{target.name} has the wrong width for its @IntDef slots")
			comp["type"] = target
			if target is None:
				own.append(comp)
		self.name_components(own, component_of, chosen)

		for s, _, _, _ in annotated:
			t = s.intdef["type"]
			if t is not None:
				if INT_BITS[t.backing] != (64 if s.jtype == "J" else 32):
					raise GenError(f"{s.cls}.{s.member} {s.where} is {s.jtype}, but its @IntDef type {t.name} is {t.backing}")
				self.slots[(s.cls, s.member, s.desc, s.where)] = t
		self.apply_rules(slots, chosen, component_of)

	def collect_slots(self, classes, chosen, param_names):
		slots = []
		for name in sorted(chosen):
			c  = classes[name]
			jn = java_name(name)
			for m in members(c):
				if m.descriptor.startswith("("):
					params, ret = cf.parse_descriptor(m.descriptor)
					types  = tuple(source_java_type(p) for p in params)
					pnames = pick_param_names(param_names(name).get((name, m.name, len(params))), params)
					for i, p in enumerate(params):
						if p in ("I", "J"):
							pname = pnames[i].rstrip("_") if pnames else f"p{i}"
							slots.append(Slot(name, m.name, m.descriptor, i, p, pname, (jn, m.name, types, i)))
					if ret in ("I", "J"):
						slots.append(Slot(name, m.name, m.descriptor, "return", ret, m.name, (jn, m.name, types, "return")))
				elif m.descriptor in ("I", "J") and not (m.access & cf.ACC_STATIC and m.access & cf.ACC_FINAL and m.constant is not None):
					slots.append(Slot(name, m.name, m.descriptor, "field", m.descriptor, m.name, (jn, m.name, None, "field")))
		return slots

	def add(self, t):
		if t.name in self.types:
			raise GenError(f"type {t.name} is declared twice")
		self.types[t.name] = t

	def build_table_types(self, classes):
		in_bit_fields = {f[1] for bf in TABLE.BIT_FIELDS.values() for f in bf["fields"]}
		for name, (kind, cls, spec) in TABLE.NEW_TYPES.items():
			fields = table_members(spec, list(self.values.get(cls, {})))
			if not fields:
				raise GenError(f"type {name}: no constants")
			if not isinstance(spec, str):
				for pattern in spec:
					if not pattern.startswith("!") and "*" not in pattern and pattern not in fields:
						raise GenError(f"type {name}: no constant {pattern}")
			t = TypedInt(name, kind, cls, [(cls, f) for f in fields])
			prefix = shared_prefix(fields) if len(fields) > 1 else spec if isinstance(spec, str) else ""
			if kind == "bit_set":
				t.backing = "u32"
				t.element = element_name(name)
				self.plan_bit_set(t, prefix)
			else:
				# A field of a signed enum is sign-extended, so an enum in a bit_field is unsigned.
				t.backing = "u32" if name in in_bit_fields else "i32"
				self.plan_enum(t, prefix)
			self.add(t)

		for name, bf in TABLE.BIT_FIELDS.items():
			cls, spec = bf["constants"]
			fields = table_members(spec, list(self.values.get(cls, {})))
			t = TypedInt(name, "bit_field", cls, [(cls, f) for f in fields])
			t.backing = bf["backing"]
			width = INT_BITS[t.backing]
			field_members = {}
			for ename, members in bf["enums"].items():
				e = TypedInt(ename, "enum", cls, [])
				e.backing, e.part_of, e.values = f"u{width}", t, dict(members)
				self.add(e)
				t.enums.append(e)
			offset = 0
			for fname, ftype, bits in bf["fields"]:
				if ftype in self.types:
					e = self.types[ftype]
					values = e.values if e.part_of else {e.members[c]: self.value(c) for c in e.consts}
					if not e.backing.startswith("u"):
						raise GenError(f"bit_field {name}: field {fname} needs an unsigned enum")
					too_big = [m for m, v in values.items() if not 0 <= v < 1 << bits]
					if too_big:
						raise GenError(f"bit_field {name}: {ftype} does not fit {bits} bits: {', '.join(too_big)}")
					field_members[ftype] = {}
					for m, v in values.items():
						field_members[ftype].setdefault(v, m)
				elif ftype not in ("bool", "_") and ftype not in INT_BITS:
					raise GenError(f"bit_field {name}: unknown field type {ftype}")
				t.fields.append((fname, ftype, bits, offset))
				offset += bits
			if offset != width:
				raise GenError(f"bit_field {name}: fields take {offset} bits, {t.backing} has {width}")

			prefix = bf.get("strip", shared_prefix(fields))
			set_fields = {}
			for c in t.consts:
				u = self.value(c) & ((1 << width) - 1)
				parts = []
				set_fields[c] = set()
				for fname, ftype, bits, off in t.fields:
					x = (u >> off) & ((1 << bits) - 1)
					if x == 0:
						continue
					set_fields[c].add(fname)
					if ftype == "_":
						raise GenError(f"bit_field {name}: {c[1]} sets padding bits")
					if ftype == "bool":
						parts.append(f"{fname} = true")
					elif ftype in field_members:
						if x in field_members[ftype]:
							parts.append(f"{fname} = .{field_members[ftype][x]}")
						elif x == (1 << bits) - 1:
							# A mask: every bit of the field, which no member names.
							parts.append(f"{fname} = {ftype}({x:#x})")
						else:
							raise GenError(f"bit_field {name}: {c[1]} has no {ftype} member for {x}")
					else:
						parts.append(f"{fname} = {x:#x}")
				t.typed.append(c)
				t.short[c] = c[1][len(prefix):] if c[1].startswith(prefix) else c[1]
				t.literals[c] = "{" + ", ".join(parts) + "}"
			for fname, ftype, bits, off in t.fields:
				if off == 0 and ftype in field_members:
					t.alone[ftype] = {c for c in t.consts if set_fields[c] <= {fname}}
			self.add(t)

	def value(self, const):
		return self.values[const[0]][const[1]]

	def plan_enum(self, t, prefix):
		bits = INT_BITS[t.backing]
		low, high = (0, 2**bits) if t.backing.startswith("u") else (-2**(bits-1), 2**(bits-1))
		for c in t.consts:
			if not low <= self.value(c) < high:
				raise GenError(f"type {t.name} ({t.backing}) cannot hold {c[1]}")
			t.members[c] = member_name(t.name, c[1][len(prefix):] if c[1].startswith(prefix) else c[1])
		if len(set(t.members.values())) != len(t.members):
			raise GenError(f"type {t.name}: members collide once {prefix} is dropped")

	def plan_bit_set(self, t, prefix):
		"""Single bits become elements. The rest, or every constant of a type in ELEMENTS, become typed constants."""
		mask = (1 << INT_BITS[t.backing]) - 1
		short = {c: c[1][len(prefix):] if c[1].startswith(prefix) else c[1] for c in t.consts}
		if t.name in TABLE.ELEMENTS:
			t.bits  = dict(TABLE.ELEMENTS[t.name])
			t.typed = list(t.consts)
		else:
			for c in t.consts:
				v = self.value(c) & mask
				if v != 0 and v & (v - 1) == 0:
					element = member_name(t.element, short[c])
					t.members[c] = element
					t.bits.setdefault(element, v.bit_length() - 1)
			t.typed = [c for c in t.consts if c not in t.members]
		by_bit = {}
		for element, bit in t.bits.items():
			by_bit.setdefault(bit, element)
		for c in t.typed:
			t.short[c] = short[c]
			v = self.value(c) & mask
			set_bits = [b for b in range(INT_BITS[t.backing]) if v >> b & 1]
			if all(b in by_bit for b in set_bits):
				t.literals[c] = "{" + ", ".join(f".{by_bit[b]}" for b in set_bits) + "}"
			else:
				t.literals[c] = None  # bits no element names: emitted with transmute

	def owner_name(self, cls):
		return self.model[cls].odin if cls in self.model else cls.rsplit("/", 1)[-1].replace("$", "_")

	def name_components(self, comps, component_of, chosen):
		"""Each @IntDef group of its own becomes a type named `<Owner>_<Thing>`."""
		named = {}
		for ref, name in TABLE.INTDEF_NAMES.items():
			named[id(component_of(ref))] = name

		by_name = collections.defaultdict(list)
		for comp in comps:
			consts = sorted(comp["consts"])
			owner = collections.Counter(c for c, _ in consts).most_common(1)[0][0]
			fields = sorted(f for _, f in consts)
			if id(comp) in named:
				name = named[id(comp)]
			else:
				prefix = shared_prefix(fields)
				if prefix:
					words = prefix.rstrip("_").split("_")
					thing = camel([w for w in words if w not in ("FLAG", "FLAGS")]) + "Flags" if comp["flag"] else camel(words)
				else:
					labels = collections.Counter()
					for s in comp["slots"]:
						label = s.member if s.where in ("field", "return") or re.match(r"(get|set|is)[A-Z]", s.member) else s.name
						label = re.sub(r"^(get|set|is)(?=[A-Z])", "", label)
						labels[tuple(re.findall(r"[A-Z]?[a-z0-9]+|[A-Z]+(?![a-z])", label[:1].upper() + label[1:]))] += 1
					thing = camel(labels.most_common(1)[0][0])
					if comp["flag"] and not thing.endswith("s"):
						thing += "Flags"
				name = f"{self.owner_name(owner)}_{thing}"
			comp["owner"] = owner if owner in chosen else comp["slots"][0].cls
			by_name[(name, comp["long"])].append(comp)

		# Groups of one family named alike are one type: their constants never overlap, or they would be one group.
		ints = {name for name, is_long in by_name if not is_long}
		for (name, is_long), group in by_name.items():
			if is_long and name in ints:
				name += "64"
			owners = {c["owner"] for c in group}
			if len(owners) > 1:
				raise GenError(f"@IntDef groups of {', '.join(sorted(owners))} are all named {name}; add one to INTDEF_NAMES")
			consts = sorted(set().union(*(c["consts"] for c in group)))
			flag = any(c["flag"] for c in group)
			t = TypedInt(name, "bit_set" if flag else "enum", group[0]["owner"], consts)
			prefix = shared_prefix([f for _, f in consts])
			if flag:
				t.backing = "u64" if is_long else "u32"
				t.element = element_name(name)
				self.plan_bit_set(t, prefix)
			else:
				t.backing = "i64" if is_long else "i32"
				self.plan_enum(t, prefix)
			self.add(t)
			for c in group:
				c["type"] = t

	def apply_rules(self, slots, chosen, component_of):
		def matches(value, pattern):
			return pattern == "*" or (value in pattern if isinstance(pattern, tuple) else value == pattern)

		unused = []
		for i, (classes, member, slot, typ) in enumerate(TABLE.SLOTS):
			t = component_of(typ)["type"] if typ.startswith("@") else self.types.get(typ)
			if t is None:
				raise GenError(f"SLOTS rule {i+1}: no type {typ}")
			hits = 0
			for s in slots:
				if not matches(s.cls, classes) or not matches(s.member, member) or not matches(s.label(), slot):
					continue
				hits += 1
				key = (s.cls, s.member, s.desc, s.where)
				if s.intdef is not None and s.intdef["type"] is not None:
					# The @IntDef wins, but a bit_field or one of its fields may take its constants.
					if t.kind == "bit_field" or t.part_of is not None:
						allowed = set(t.consts) if t.kind == "bit_field" else t.part_of.alone.get(t.name, set())
						if not s.intdef["consts"] <= allowed:
							raise GenError(f"SLOTS rule {i+1}: {s.cls}.{s.member} has @IntDef constants {t.name} does not take")
						self.slots[key] = t
					elif not s.intdef["consts"] <= set(t.consts) and s.intdef["type"] is not t:
						raise GenError(f"SLOTS rule {i+1}: {s.cls}.{s.member} has @IntDef constants {t.name} does not take")
					continue
				if INT_BITS[t.backing] != (64 if s.jtype == "J" else 32):
					raise GenError(f"SLOTS rule {i+1}: {s.cls}.{s.member} is {'long' if s.jtype == 'J' else 'int'}, {t.name} is {t.backing}")
				if self.slots.get(key, t) is not t:
					raise GenError(f"{s.cls}.{s.member} {s.where} is typed twice, by {self.slots[key].name} and {t.name}")
				self.slots[key] = t
			if hits == 0:
				unused.append(f"SLOTS rule {i+1} ({classes} {member} {slot})")
		unused += [f"ELEMENTS {n}" for n in TABLE.ELEMENTS if n not in self.types]
		unused += [f"NUMBER_KEYS {n}" for n in TABLE.NUMBER_KEYS if n not in self.types]
		if unused:
			raise GenError("table.py entries that match nothing:\n\t" + "\n\t".join(unused))

	def of(self, cls, member, desc, where):
		return self.slots.get((cls, member, desc, where))


#
# Emission
#

def to_jni(t, jtype, value):
	"""A typed value as the JNI integer it is passed as."""
	jni = "i64" if jtype == "J" else "i32"
	return f"{jni}({value})" if t.kind == "enum" else f"transmute({jni}){value}"


def from_jni(t, value):
	return f"{t.name}({value})" if t.kind == "enum" else f"transmute({t.name})({value})"


class Emitter:
	def __init__(self, platform, model, types):
		self.platform = platform
		self.model    = model
		self.types    = types
		self.stats    = collections.Counter()
		self.names    = {}  # Odin name -> the Java declaration behind it, to catch clashes

	def param_type(self, jc, m, where, desc):
		t = self.types.of(jc.name, m.name, m.descriptor, where)
		return t.name if t else odin_ref(self.model, desc)

	def typed_int(self, t):
		"""An enum, a bit_set with its element enum, or a bit_field with its field enums, then its typed constants."""
		what = f"typed constants of {java_name(t.owner)}"

		def enum_block(name, backing, rows):
			self.declare(name, what)
			width = max((len(m) for m, _ in rows), default=0)
			return [f"{name} :: enum {backing} {{", *(f"\t{m.ljust(width)} = {v}," for m, v in rows), "}"]

		lines = []
		if t.kind == "enum":
			lines += enum_block(t.name, t.backing, [(t.members[c], self.types.value(c)) for c in t.consts])
		elif t.kind == "bit_set":
			lines += enum_block(t.element, t.backing, list(t.bits.items()))
			self.declare(t.name, what)
			lines.append(f"{t.name} :: distinct bit_set[{t.element}; {t.backing}]")
		else:
			for e in t.enums:
				lines += enum_block(e.name, e.backing, [(m, hex(v) if v > 9 else v) for m, v in e.values.items()])
				lines.append("")
			rows = []
			for fname, ftype, bits, _ in t.fields:
				if ftype == "_":
					ftype = "u8" if bits <= 8 else "u16" if bits <= 16 else "u32"
				rows.append((f"{fname}:", ftype, bits))
			name_w = max(len(r[0]) for r in rows)
			type_w = max(len(r[1]) for r in rows)
			self.declare(t.name, what)
			lines.append(f"{t.name} :: bit_field {t.backing} {{")
			lines += [f"\t{n.ljust(name_w)} {ty.ljust(type_w)} | {b}," for n, ty, b in rows]
			lines.append("}")

		consts = []
		for c in t.typed:
			name = f"{t.name}_{t.short[c]}"
			self.declare(name, f"{java_name(c[0])}.{c[1]}")
			literal = t.literals[c]
			if literal is None:
				mask = (1 << INT_BITS[t.backing]) - 1
				literal = f"transmute({t.name}){t.backing}({hex(self.types.value(c) & mask)})"
			else:
				literal = t.name + literal
			consts.append((name, literal))
		if consts:
			width = max(len(n) for n, _ in consts)
			lines.append("")
			lines += [f"{n.ljust(width)} :: {v}" for n, v in consts]
		self.stats["types"] += 1
		return "\n".join(lines)

	def declare(self, name, what):
		if name in self.names or name in HAND_WRITTEN_NAMES:
			raise GenError(f"{name} is declared by both {what} and {self.names.get(name, 'java.odin')}")
		self.names[name] = what

	def since(self, jc, member=None):
		class_since = self.platform.since.get(jc.name, 0)
		if member is None:
			level = class_since
		else:
			level = self.platform.since.get(f"{jc.name}#{member}", 0)
			if level <= class_since:
				level = 0
		return f" // API level {level}" if level > MIN_API_LEVEL else ""

	def class_type(self, jc):
		self.declare(jc.odin, java_name(jc.name))
		kind   = "interface" if is_interface(jc.cls) else "class"
		parent = self.model[jc.parent].odin
		fields = [("using " + parent, parent)] + [(self.model[v].odin, self.model[v].odin) for v in jc.views]
		width  = max(len(n) for n, _ in fields) + 1
		lines  = [f"// {kind} {java_name(jc.name)}{self.since(jc)}", f"{jc.odin} :: struct #raw_union {{"]
		for n, t in fields:
			lines.append(f"\t{(n + ':').ljust(width)} {t},")
		lines.append("}")
		return "\n".join(lines)

	def class_members(self, jc, param_names):
		out = []
		if jc.name in HAND_WRITTEN_TYPES:
			out.append(f"// class {java_name(jc.name)}, whose type is in java.odin")
		cache = f"{jc.odin}__class"
		self.declare(cache, java_name(jc.name))
		out.append(f"@(private)\n{cache} := Cached_Class{{name = \"{jc.name}\"}}")

		constants = []
		fields    = []
		groups    = collections.OrderedDict()
		for m in members(jc.cls):
			if m.descriptor.startswith("("):
				groups.setdefault("new" if m.name == "<init>" else m.name, []).append(m)
			elif m.access & cf.ACC_STATIC and m.access & cf.ACC_FINAL and m.constant is not None:
				constants.append(m)
			else:
				fields.append(m)

		if constants:
			width = max(len(f"{jc.odin}_{f.name}") for f in constants)
			rows = []
			for f in constants:
				name = f"{jc.odin}_{f.name}"
				self.declare(name, f"{java_name(jc.name)}.{f.name}")
				rows.append(f"{name.ljust(width)} :: {odin_constant(f.descriptor, f.constant)}{self.since(jc, f.name)}")
			self.stats["constants"] += len(rows)
			out.append("\n".join(rows))

		for f in fields:
			out.extend(self.field_accessors(jc, f))

		for name, overloads in groups.items():
			base = f"{jc.odin}_{name}"
			if len(overloads) == 1:
				out.append(self.method(jc, overloads[0], base, param_names))
				continue
			group, signatures = [], set()
			for m in overloads:
				params, _ = cf.parse_descriptor(m.descriptor)
				member = f"{base}_{'_'.join(overload_suffix(self.model, p) for p in params) or 'void'}"
				while member in self.names:
					member += "_"
				out.append(self.method(jc, m, member, param_names))
				# Overloads that look the same to Odin cannot share a group; the first one stays in it.
				signature = tuple(self.param_type(jc, m, i, p) for i, p in enumerate(params))
				if not m.access & cf.ACC_STATIC and m.name != "<init>":
					signature = (f"^{jc.odin}",) + signature
				if signature not in signatures:
					signatures.add(signature)
					group.append(member)
			self.declare(base, f"{java_name(jc.name)}.{name}")
			out.append(f"{base} :: proc{{\n" + "".join(f"\t{n},\n" for n in group) + "}")
		return out

	def field_accessors(self, jc, f):
		static = bool(f.access & cf.ACC_STATIC)
		typed  = self.types.of(jc.name, f.name, f.descriptor, "field")
		typ    = typed.name if typed else odin_ref(self.model, f.descriptor)
		kind   = call_kind(f.descriptor)
		jstat  = "Static" if static else ""
		target = "jni_class" if static else "self"
		params = "" if static else f"self: ^{jc.odin}"
		lookup = f"jni_field(&jni_cache, &{jc.odin}__class, \"{f.name}\", \"{f.descriptor}\", {str(static).lower()})"
		locals = "jni_env, jni_class, jni_id" if static else "jni_env, _, jni_id"
		since  = self.since(jc, f.name)

		get = f"jni_env->Get{jstat}{kind}Field({target}, jni_id)"
		if f.descriptor == "Z":
			get += " != 0"
		elif kind == "Object":
			get = f"({typ})({get})"
		elif typed:
			get = from_jni(typed, get)

		name = f"{jc.odin}_get_{f.name}"
		self.declare(name, f"{java_name(jc.name)}.{f.name}")
		out = ["\n".join([
			f"{name} :: proc \"contextless\" ({params}) -> (result: {typ}, exception: ^Throwable) {{{since}",
			"\t@(static) jni_cache: Cached_Field",
			f"\t{locals} := {lookup} or_return",
			f"\treturn {get}, jni_take(jni_env)",
			"}",
		])]
		self.stats["fields"] += 1

		if not f.access & cf.ACC_FINAL:
			value = "android.jboolean(value)" if f.descriptor == "Z" else to_jni(typed, f.descriptor, "value") if typed else "value"
			name  = f"{jc.odin}_set_{f.name}"
			self.declare(name, f"{java_name(jc.name)}.{f.name}")
			out.append("\n".join([
				f"{name} :: proc \"contextless\" ({params + ', ' if params else ''}value: {typ}) -> (exception: ^Throwable) {{{since}",
				"\t@(static) jni_cache: Cached_Field",
				f"\t{locals} := {lookup} or_return",
				f"\tjni_env->Set{jstat}{kind}Field({target}, jni_id, {value})",
				"\treturn jni_take(jni_env)",
				"}",
			]))
		return out

	def method(self, jc, m, name, param_names):
		self.declare(name, f"{java_name(jc.name)}.{m.name}")
		static = bool(m.access & cf.ACC_STATIC)
		ctor   = m.name == "<init>"
		params, ret = cf.parse_descriptor(m.descriptor)

		names = pick_param_names(param_names.get((jc.name, m.name, len(params))), params)
		if names is None and ctor and is_inner_class(jc.cls) and params[:1] == [f"L{jc.name.rsplit('$', 1)[0]};"]:
			# An inner class's constructor takes its outer instance first, which the source does not show.
			rest = pick_param_names(param_names.get((jc.name, m.name, len(params)-1)), params[1:])
			if rest is not None and "outer" not in rest:
				names = ["outer"] + rest
		if names is None and jc.cls.access & cf.ACC_ENUM and m.name == "valueOf" and params == ["Ljava/lang/String;"]:
			names = ["name"]
		if names is None:
			names = [f"p{i}" for i in range(len(params))]
			if params:
				self.stats["unnamed"] += 1

		sig = [] if static or ctor else [f"self: ^{jc.odin}"]
		sig += [f"{n}: {self.param_type(jc, m, i, p)}" for i, (n, p) in enumerate(zip(names, params))]
		typed_ret = self.types.of(jc.name, m.name, m.descriptor, "return")

		if ctor:
			results = f"(result: ^{jc.odin}, exception: ^Throwable)"
		elif ret == "V":
			results = "(exception: ^Throwable)"
		else:
			results = f"(result: {typed_ret.name if typed_ret else odin_ref(self.model, ret)}, exception: ^Throwable)"

		lookup = f"jni_method(&jni_cache, &{jc.odin}__class, \"{m.name}\", \"{m.descriptor}\", {str(static).lower()})"
		lines = [
			f"{name} :: proc \"contextless\" ({', '.join(sig)}) -> {results} {{{self.since(jc, m.name + m.descriptor)}",
			"\t@(static) jni_cache: Cached_Method",
			f"\t{'jni_env, jni_class, jni_id' if static or ctor else 'jni_env, _, jni_id'} := {lookup} or_return",
		]

		if params:
			values = []
			for i, (n, p) in enumerate(zip(names, params)):
				typed = self.types.of(jc.name, m.name, m.descriptor, i)
				if p == "Z":
					values.append(f"{{z = android.jboolean({n})}}")
				elif typed:
					values.append(f"{{{PRIMITIVES[p][1]} = {to_jni(typed, p, n)}}}")
				elif p in PRIMITIVES:
					values.append(f"{{{PRIMITIVES[p][1]} = {n}}}")
				else:
					values.append(f"{{l = {n}}}")
			lines.append(f"\tjni_args := [?]android.jvalue{{{', '.join(values)}}}")
			args = "&jni_args[0]"
		else:
			args = "nil"

		if ctor:
			lines.append(f"\treturn (^{jc.odin})(jni_env->NewObjectA(jni_class, jni_id, {args})), jni_take(jni_env)")
		else:
			kind = call_kind(ret)
			if static:
				call = f"jni_env->CallStatic{kind}MethodA(jni_class, jni_id, {args})"
			else:
				call = f"jni_env->Call{kind}MethodA(self, jni_id, {args})"
			if ret == "V":
				lines += [f"\t{call}", "\treturn jni_take(jni_env)"]
			elif ret == "Z":
				lines.append(f"\treturn {call} != 0, jni_take(jni_env)")
			elif kind == "Object":
				lines.append(f"\treturn ({odin_ref(self.model, ret)})({call}), jni_take(jni_env)")
			elif typed_ret:
				lines.append(f"\treturn {from_jni(typed_ret, call)}, jni_take(jni_env)")
			else:
				lines.append(f"\treturn {call}, jni_take(jni_env)")
		lines.append("}")
		self.stats["methods"] += 1
		return "\n".join(lines)


def file_name(java_package):
	return java_package.replace(".", "_") + ".odin"


def file_header(imports_android, comment=None):
	lines = [GENERATED_MARKER, "#+build linux", f"package {PACKAGE}", ""]
	if comment:
		lines += [comment, ""]
	if imports_android:
		lines += ["import android \"core:sys/android\"", ""]
	return "\n".join(lines) + "\n"


def print_stats(model, chosen):
	rows = collections.defaultdict(collections.Counter)
	for name in chosen:
		row = rows[package_of(name)]
		row["classes"] += 1
		for m in members(model[name].cls):
			if m.descriptor.startswith("("):
				row["methods"] += 1
			elif m.access & cf.ACC_STATIC and m.access & cf.ACC_FINAL and m.constant is not None:
				row["constants"] += 1
			else:
				row["fields"] += 1
	print(f"{'package':<28} {'classes':>8} {'methods':>8} {'fields':>8} {'constants':>10}")
	total = collections.Counter()
	for pkg in sorted(rows):
		r = rows[pkg]
		total.update(r)
		print(f"{pkg:<28} {r['classes']:>8} {r['methods']:>8} {r['fields']:>8} {r['constants']:>10}")
	print(f"{'total':<28} {total['classes']:>8} {total['methods']:>8} {total['fields']:>8} {total['constants']:>10}")
	print(f"{len(model) - len(chosen)} more classes get a type only")


def main():
	ap = argparse.ArgumentParser(description="Generate vendor:android/java from android.jar.")
	ap.add_argument("--sdk", default=os.environ.get("ODIN_ANDROID_SDK"), help="SDK root (default: $ODIN_ANDROID_SDK)")
	ap.add_argument("--platform", default="android-37.2", help="platform directory under <sdk>/platforms")
	ap.add_argument("--stats", action="store_true", help="print counts per Java package and generate nothing")
	args = ap.parse_args()
	if not args.sdk:
		raise GenError("pass --sdk or set ODIN_ANDROID_SDK")

	platform = Platform(args.sdk, args.platform)
	model, chosen = build_model(platform, PACKAGES)
	if args.stats:
		print_stats(model, chosen)
		return

	sources = {}

	def param_names(name):
		outer = name.split("$")[0]
		if outer not in sources:
			sources[outer] = source_param_names(platform, outer)
		return sources[outer]

	types = Types(platform, model, chosen, param_names)
	owned = collections.defaultdict(list)
	for t in types.types.values():
		if t.part_of is None:
			owned[t.owner].append(t)

	emitter = Emitter(platform, model, types)
	files = collections.defaultdict(list)
	for name in sorted(model, key=lambda n: (package_of(n), n)):
		jc  = model[name]
		out = file_name(package_of(name)) if jc.selected else "other_packages.odin"
		if name not in HAND_WRITTEN_TYPES:
			files[out].append(emitter.class_type(jc))
		if jc.selected:
			files[out].extend(emitter.class_members(jc, param_names(name)))
			files[out].extend(emitter.typed_int(t) for t in owned.pop(name, []))
	if owned:
		raise GenError("types whose classes are not bound: " + ", ".join(t.name for ts in owned.values() for t in ts))

	# Only generated files are overwritten or deleted.
	def is_generated(path):
		with open(path, encoding="utf-8") as f:
			return f.readline().rstrip("\r\n") == GENERATED_MARKER

	for fn in os.listdir(OUT_DIR):
		path = os.path.join(OUT_DIR, fn)
		if fn.endswith(".odin") and fn not in files and is_generated(path):
			os.remove(path)

	lines = 0
	for fn in sorted(files):
		path = os.path.join(OUT_DIR, fn)
		if os.path.exists(path) and not is_generated(path):
			raise GenError(f"{path} is not generated; refusing to overwrite it")
		other = fn == "other_packages.odin"
		comment = "// The classes outside PACKAGES that the wrappers refer to. Only their types are generated." if other else None
		text = file_header(not other, comment) + "\n\n".join(files[fn]) + "\n"
		lines += text.count("\n")
		with open(path, "w", encoding="utf-8", newline="\n") as f:
			f.write(text)

	s = emitter.stats
	print(f"{len(chosen)} classes with members and {len(model) - len(chosen)} more types: {s['methods']} methods "
		f"({s['unnamed']} without parameter names), {s['fields']} fields, {s['constants']} constants; "
		f"{s['types']} typed integers, which {len(types.slots)} slots take; {lines} lines in {len(files)} files")


if __name__ == "__main__":
	try:
		main()
	except GenError as e:
		sys.exit(f"error: {e}")
